def _validate_run_id(run_id: str) -> None:
    if not run_id or run_id in {".", ".."} or "/" in run_id or "\x00" in run_id:
        raise ValueError("run_id must be a single nonempty filename component")


def _decode_entry(value: object) -> FleetEntry:
    if not isinstance(value, dict) or set(value) != {
        field.name for field in fields(FleetEntry)
    }:
        raise ValueError("Invalid fleet entry fields")
    if type(value["schema_version"]) is not int or value["schema_version"] != 1:
        raise ValueError("Unsupported fleet schema version")
    if type(value["pid"]) is not int or value["pid"] <= 0:
        raise ValueError("Fleet pid must be a positive integer")
    for name in ("root", "process_start", "run_id", "agent", "started_at"):
        if not isinstance(value[name], str) or not value[name]:
            raise ValueError(f"Fleet {name} must be a nonempty string")
    _validate_run_id(value["run_id"])
    validate_timestamp(value["started_at"], "started_at")
    return FleetEntry(
        schema_version=value["schema_version"],
        root=Path(value["root"]),
        pid=value["pid"],
        process_start=value["process_start"],
        run_id=value["run_id"],
        agent=value["agent"],
        started_at=value["started_at"],
    )


def _read_entry(path: Path, directory: int) -> FleetEntry:
    descriptor = os.open(
        path.name,
        os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NONBLOCK,
        dir_fd=directory,
    )
    with os.fdopen(descriptor, "rb") as stream:
        if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
            raise ValueError("Fleet entry is not a regular file")
        encoded = stream.read(MAX_STATE_BYTES + 1)
    if len(encoded) > MAX_STATE_BYTES:
        raise ValueError("Fleet entry exceeds size limit")
    entry = _decode_entry(decode_json(encoded.decode("utf-8"), source=str(path)))
    if path.name != f"{entry.run_id}.json":
        raise ValueError("Fleet filename does not match run_id")
    return entry


class FleetRegistry:
    """Publish durable fleet records; snapshots never take mutation locks."""

def run(self) -> SupervisorOutcome:
    self._sessions = 0
    self._state_halt = None
    with RunLock.acquire(self._paths.run_lock):
        require_no_emergency_failure(self._paths)
        reconcile_metrics(self._paths)
        try:
            self._reconcile_capabilities()
            state = self._store.read()
            batch = state["batch"]
            if (
                not batch["id"]
                or not batch["started_at"]
                or batch["status"] == "idle"
            ):
                StateService(self._store).start_batch(
                    uuid4().hex,
                    _timestamp(self._clock.now()),
                    expected_revision=state["revision"],
                )
        except _STATE_ERRORS:
            return SupervisorOutcome(1, self._state_failure("startup"), 0)
        metadata, entry = self._publish_ownership()
        try:
            with supervisor_signal_scope():
                decision = self._loop()
        except SupervisorSignal as error:
            self._record_stop(supervisor_exit_code(error) - 128)
            return SupervisorOutcome(
                supervisor_exit_code(error),
                SupervisorDecision(DecisionKind.HALT, "supervisor signal"),
                self._sessions,
            )
        finally:
            self._run_id = None
            cleanup_run_records(self._paths, metadata, entry)
    terminal_ok = decision.kind in (DecisionKind.PAUSE, DecisionKind.COMPLETE)
    return SupervisorOutcome(0 if terminal_ok else 1, decision, self._sessions)

def _state_failure(self, site: str) -> SupervisorDecision:
    detail = "Supervisor state operation failed; inspect state before restarting."

    def write_notice(site: str, detail: str) -> None:
        def mutate(state: State) -> None:
            if state["control"]["attention"] is None:
                state["control"]["attention"] = {
                    "site": site,
                    "detail": detail,
                    "created_at": _timestamp(self._clock.now()),
                }

        self._store.transaction(mutate)

    record_state_failure(
        self._paths, site=site, detail=detail, write_state_notice=write_notice
    )
    self._state_halt = SupervisorDecision(DecisionKind.HALT, detail)
    return self._state_halt

def _record_stop(self, number: int) -> None:
    def mutate(state: State) -> None:
        state["control"]["pause_requested"] = True
        if state["control"]["pause_reason"] is None:
            state["control"]["pause_reason"] = {
                "site": "operator_stop",
                "detail": f"Supervisor received signal {number}.",
                "created_at": _timestamp(self._clock.now()),
            }

    try:
        self._store.transaction(mutate)
    except _STATE_ERRORS:
        self._state_failure("operator_stop")

def _publish_ownership(self) -> tuple[SessionMetadata, FleetEntry]:
    run_id = uuid4().hex
    identity = process_identity(os.getpid())
    assert identity is not None
    started_at = _timestamp(self._clock.now())
    metadata = SessionMetadata(
        1,
        run_id,
        run_id,
        self._driver.name,
        identity.pid,
        identity.started,
        started_at,
    )
    entry = FleetEntry(
        1,
        self._paths.project_root,
        identity.pid,
        identity.started,
        run_id,
        self._driver.name,
        started_at,
    )
    publish_run_metadata(self._paths, metadata)
    FleetRegistry(self._paths.fleet_root).publish(entry)
    self._run_id = run_id

def _emergency_fields(pairs: list[tuple[str, object]]) -> dict[str, object]:
    record: dict[str, object] = {}
    for key, value in pairs:
        if key in record:
            raise ValueError("duplicate emergency record field")
        record[key] = value
    return record


def _read_emergency(marker: Path) -> tuple[bytes, os.stat_result] | None:
    try:
        information = marker.lstat()
    except FileNotFoundError:
        return None
    if (
        not stat.S_ISREG(information.st_mode)
        or stat.S_IMODE(information.st_mode) != 0o600
    ):
        raise ValueError("emergency evidence must be a private regular file")
    descriptor = os.open(marker, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(descriptor, "rb") as stream:
        opened = os.fstat(stream.fileno())
        if not os.path.samestat(information, opened):
            raise ValueError("emergency evidence changed while opening")
        payload = stream.read(MAX_STATE_BYTES + 1)
    if len(payload) > MAX_STATE_BYTES:
        raise ValueError("emergency evidence exceeds maximum document size")
    try:
        record = json.loads(payload, object_pairs_hook=_emergency_fields)
    except RecursionError as error:
        raise ValueError("emergency evidence exceeds maximum nesting") from error
    if not isinstance(record, dict) or set(record) != {
        "schema_version",
        "site",
        "detail",
        "created_at",
    }:
        raise ValueError("invalid emergency record fields")
    for field in ("site", "detail"):
        if not isinstance(record[field], str):
            raise TypeError(f"emergency {field} must be a string")
    validate_timestamp(record["created_at"], "emergency.created_at")
    _encode_record(record)
    if not os.path.samestat(information, marker.lstat()):
        raise ValueError("emergency evidence changed while reading")
    return payload, information


